// Build a single, language-consistent prompt.
// The customer message and history arrive from the FastAPI backend.

const input = $json.body ?? $json;
const userMessage = input.user_message || '';
const history = input.conversation_history || '';
const products = input.product_context || '';
const preferred = input.preferred_language || 'fr';
const systemPrompt = input.system_prompt || '';

// Detect whether the customer wrote in Arabic script (Darija / MSA).
const arabicRatio = (userMessage.match(/[\u0600-\u06FF]/g) || []).length / Math.max(userMessage.length, 1);
const isArabic = arabicRatio > 0.3;

let languageInstruction;
if (isArabic) {
  languageInstruction =
    'IMPORTANT — LANGUAGE: The customer wrote in ARABIC SCRIPT (Tunisian Darija). ' +
    'Reply in Tunisian Darija (العربية التونسية), using natural everyday language ' +
    'like a Tunisian shop assistant would speak, e.g. "شكون" "باش" "أصلي" "السبر" "ماشي" "برشا". ' +
    'Keep the product names as they are. Do NOT reply in formal French.';
} else if (preferred === 'ar') {
  languageInstruction = 'Reply in Tunisian Darija (العربية التونسية), naturally and warmly.';
} else if (preferred === 'en') {
  languageInstruction = 'Reply in English.';
} else {
  languageInstruction = 'Reply in French.';
}

const prompt = systemPrompt + '\n\n' + languageInstruction + '\n\n' +
  'CONTEXTE PRODUITS :\n' + products + '\n\n' +
  'HISTORIQUE DE LA CONVERSATION :\n' + (history || 'Aucun historique.') + '\n\n' +
  'client: ' + userMessage + '\nvendeur:';

// Keep the ORDER block instruction from the system prompt intact so orders
// can still be auto-created by the backend after parsing the reply.
return [{
  json: {
    prompt: prompt,
    language: isArabic ? 'darija' : (preferred === 'ar' ? 'darija' : preferred),
    reply_language: preferred
  }
}];

// Discard NVIDIA plumbing and return only { reply, language }.
const data = $json.body ?? $json;
const reply = data?.choices?.[0]?.message?.content || '';
const language = $('Build Prompt').first().json.language || 'fr';

return [{
  json: {
    reply: reply,
    language: language
  }
}];
